using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;

namespace ClearSpace {
public static class RecoveryTests {
 static void MarkRestored(string manifest,RecoveryEntry entry){entry.Restored=true;byte[] bytes=ProtectedData.Protect(Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(entry)),null,DataProtectionScope.CurrentUser);File.AppendAllText(manifest,Convert.ToBase64String(bytes)+"\n");}
 public static int Run(string output){Directory.CreateDirectory(output);var tests=new List<string>();Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("FAILED: "+label);tests.Add("PASS: "+label);};string fixture=Path.Combine(Path.GetFullPath(output),"recovery-fixture-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(fixture);
  Func<string,int,CleanResult> backup=(name,count)=>{string directory=Path.Combine(fixture,name);Directory.CreateDirectory(directory);for(int i=0;i<count;i++){string file=Path.Combine(directory,i+".bin");File.WriteAllText(file,"fixture "+name+" "+i);File.SetLastWriteTimeUtc(file,DateTime.UtcNow.AddDays(-10));}var rule=new Rule(name,name,"软件缓存","","",new[]{directory},1,true);var engine=new Engine(new List<Rule>{rule}){UseFileBackup=true,FileBackupDirectory=Path.Combine(fixture,"backups"),IsRunning=owners=>false};return engine.Clean(engine.Scan(CancellationToken.None,null),true,CancellationToken.None,null);};
  try{
   var original=backup("complete",3);string batch=Path.GetDirectoryName(original.FileBackupManifest);var entries=FileRecovery.Read(original.FileBackupManifest);var restored=FileRecovery.RestoreDetailed(original.FileBackupManifest,true);check(restored.Restored==3&&restored.Cleared==3&&restored.Pending==0&&restored.Failed==0,"Successful restore verifies and automatically removes each corresponding backup");check(entries.All(e=>File.Exists(e.Original)&&new FileInfo(e.Original).Length==e.Bytes),"Every restored original has its recorded content size");check(!File.Exists(original.FileBackupManifest)&&!Directory.Exists(batch)&&Directory.Exists(Path.GetDirectoryName(batch)),"Complete restoration removes the spent index and empty batch while retaining the configured backup root");
   original=backup("partial",3);entries=FileRecovery.Read(original.FileBackupManifest);File.WriteAllText(entries[0].Original,"new personal content");restored=FileRecovery.RestoreDetailed(original.FileBackupManifest,true);check(restored.Restored==2&&restored.Cleared==2&&restored.Skipped==1&&restored.Pending==1,"A partially restored batch keeps only the unresolved backup in its journal");check(File.ReadAllText(entries[0].Original)=="new personal content"&&File.Exists(Path.Combine(Path.GetDirectoryName(original.FileBackupManifest),entries[0].Stored)),"Conflicting original files are never overwritten or used to discard their backups");check(FileRecovery.Read(original.FileBackupManifest).Single().Stored==entries[0].Stored,"The remaining backup is still authenticated and selectable for another restore");File.Delete(entries[0].Original);check(FileRecovery.Restore(original.FileBackupManifest)==1&&!File.Exists(original.FileBackupManifest),"A later restore completes and automatically clears the remaining backup");
   original=backup("corrupt",2);entries=FileRecovery.Read(original.FileBackupManifest);string corrupt=Path.Combine(Path.GetDirectoryName(original.FileBackupManifest),entries[0].Stored);File.AppendAllText(corrupt,"tampered");restored=FileRecovery.RestoreDetailed(original.FileBackupManifest,true);check(restored.Restored==1&&restored.Cleared==1&&restored.Failed==1&&restored.Pending==1,"A corrupt backup is retained while unrelated valid entries finish restoring");check(File.Exists(corrupt)&&!File.Exists(entries[0].Original),"Failed content verification never creates an original or purges its backup");
   original=backup("blocked",1);entries=FileRecovery.Read(original.FileBackupManifest);string parent=Path.GetDirectoryName(entries[0].Original);Directory.Delete(parent,false);File.WriteAllText(parent,"not a directory");restored=FileRecovery.RestoreDetailed(original.FileBackupManifest,true);check(restored.Failed==1&&restored.Cleared==0&&File.Exists(Path.Combine(Path.GetDirectoryName(original.FileBackupManifest),entries[0].Stored)),"An unwritable or invalid restore destination leaves the backup untouched");
   original=backup("resume",1);entries=FileRecovery.Read(original.FileBackupManifest);check(FileRecovery.Restore(original.FileBackupManifest,false)==1,"An isolated compatibility restore can retain its backup for journal recovery checks");MarkRestored(original.FileBackupManifest,entries[0]);restored=FileRecovery.RestoreDetailed(original.FileBackupManifest,true);check(restored.Restored==0&&restored.Cleared==1&&restored.Pending==0,"Cleanup resumes after an interrupted restore without overwriting the already verified original");
   original=backup("changed-after-restore",1);entries=FileRecovery.Read(original.FileBackupManifest);FileRecovery.Restore(original.FileBackupManifest,false);MarkRestored(original.FileBackupManifest,entries[0]);File.AppendAllText(entries[0].Original," user edits");restored=FileRecovery.RestoreDetailed(original.FileBackupManifest,true);check(restored.Cleared==0&&restored.Skipped==1&&restored.Pending==1,"A changed original after interruption prevents automatic backup removal");
   original=backup("delete-interrupted",1);entries=FileRecovery.Read(original.FileBackupManifest);FileRecovery.Restore(original.FileBackupManifest,false);MarkRestored(original.FileBackupManifest,entries[0]);File.Delete(Path.Combine(Path.GetDirectoryName(original.FileBackupManifest),entries[0].Stored));restored=FileRecovery.RestoreDetailed(original.FileBackupManifest,true);check(restored.Cleared==1&&!File.Exists(original.FileBackupManifest),"A completed data deletion can be reconciled when the final journal marker was interrupted");
   original=backup("journal-tail",1);File.AppendAllText(original.FileBackupManifest,"interrupted-record");restored=FileRecovery.RestoreDetailed(original.FileBackupManifest,true);check(restored.Restored==1&&restored.Cleared==1&&!File.Exists(original.FileBackupManifest),"Restore recovers from an incomplete trailing journal record before appending cleanup states");
   original=backup("foreign-file",1);batch=Path.GetDirectoryName(original.FileBackupManifest);string foreign=Path.Combine(batch,"keep.txt");File.WriteAllText(foreign,"unrelated");restored=FileRecovery.RestoreDetailed(original.FileBackupManifest,true);check(restored.Cleared==1&&File.Exists(foreign)&&Directory.Exists(batch),"Automatic cleanup never deletes unrelated files in a backup batch");
   original=backup("purge-locked",1);entries=FileRecovery.Read(original.FileBackupManifest);using(var gate=FileRecovery.OpenBatchLock(original.FileBackupManifest)){bool purgeBlocked=false,restoreBlocked=false;try{FileRecovery.Purge(original.FileBackupManifest);}catch(IOException){purgeBlocked=true;}try{FileRecovery.RestoreDetailed(original.FileBackupManifest,true);}catch(IOException){restoreBlocked=true;}check(purgeBlocked&&restoreBlocked&&File.Exists(Path.Combine(Path.GetDirectoryName(original.FileBackupManifest),entries[0].Stored)),"Restore and purge respect the same exclusive batch lock without deleting backup data");}FileRecovery.Purge(original.FileBackupManifest);check(!Directory.Exists(Path.GetDirectoryName(original.FileBackupManifest)),"Purge completes after the batch lock is released");
   original=backup("purge-interrupted",2);entries=FileRecovery.Read(original.FileBackupManifest);string held=Path.Combine(Path.GetDirectoryName(original.FileBackupManifest),entries[1].Stored);using(var handle=new FileStream(held,FileMode.Open,FileAccess.Read,FileShare.Read)){bool failed=false;try{FileRecovery.Purge(original.FileBackupManifest);}catch(IOException){failed=true;}check(failed&&FileRecovery.Read(original.FileBackupManifest).Count==1&&File.Exists(held),"An interrupted purge journals completed deletions and retains its unresolved backup");}FileRecovery.Purge(original.FileBackupManifest);check(!File.Exists(original.FileBackupManifest),"An interrupted purge can safely resume and remove its spent index");
   original=backup("open-folder",1);check(BackupFolders.Resolve(Path.Combine(fixture,"configured"),original.FileBackupManifest)==Path.GetDirectoryName(original.FileBackupManifest),"Open backup location prefers the most recent real backup batch");FileRecovery.Restore(original.FileBackupManifest);check(BackupFolders.Resolve(Path.Combine(fixture,"configured"),original.FileBackupManifest)==Path.GetFullPath(Path.Combine(fixture,"configured")),"After automatic cleanup, opening backups falls back to the configured root");
   File.WriteAllLines(Path.Combine(output,"recovery-test-results.txt"),tests.Concat(new[]{"ALL "+tests.Count+" RECOVERY CHECKS PASSED","Only generated workspace fixtures were modified."}));return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(output,"recovery-test-results.txt"),String.Join("\n",tests)+"\n"+ex);return 1;}
 }
}
}
